<script setup lang="ts">
import axios from 'axios';
import { computed, onMounted, reactive, ref } from 'vue';
import { RouterLink } from 'vue-router';
import BaseModal from '@/components/common/BaseModal.vue';
import http from '@/api/http';
import { useAuthStore } from '@/stores/auth';

interface PermissionRecord { id: number; name: string; guard_name: string; group: string; group_key: string; roles_count: number; other_roles_count: number; users_count: number; is_assigned: boolean; is_protected: boolean; can_rename: boolean; can_trash: boolean; created_at: string | null }
interface ApiError { message?: string; errors?: Record<string, string[]> }
interface PaginationMeta { current_page: number; last_page: number; total: number }
const auth = useAuthStore();
const permissions = ref<PermissionRecord[]>([]);
const loading = ref(false);
const submitting = ref(false);
const bulkSubmitting = ref(false);
const modalOpen = ref(false);
const detailsOpen = ref(false);
const editingPermission = ref<PermissionRecord | null>(null);
const selectedPermission = ref<PermissionRecord | null>(null);
const form = reactive({ name: '' });
const search = ref('');
const group = ref('');
const guard = ref('');
const groupOptions = ref<string[]>([]);
const bulkAction = ref('');
const selectedIds = ref<number[]>([]);
const message = ref('');
const errorMessage = ref('');
const validationErrors = ref<Record<string, string[]>>({});
const pagination = ref<PaginationMeta>({ current_page: 1, last_page: 1, total: 0 });
const canCreate = computed(() => auth.can('permissions.create'));
const canUpdate = computed(() => auth.can('permissions.update'));
const canDelete = computed(() => auth.can('permissions.delete'));
const canRestore = computed(() => auth.can('permissions.restore'));
const canForceDelete = computed(() => auth.can('permissions.force_delete'));
const selectedCount = computed(() => selectedIds.value.length);
const allSelected = computed(() => permissions.value.filter((item) => item.can_trash).length > 0 && permissions.value.filter((item) => item.can_trash).every((item) => selectedIds.value.includes(item.id)));
function fieldError(field: string): string { return validationErrors.value[field]?.[0] ?? ''; }
function handleError(error: unknown, fallback: string): void { if (axios.isAxiosError<ApiError>(error)) { validationErrors.value = error.response?.data?.errors ?? {}; errorMessage.value = error.response?.data?.message ?? fallback; } else errorMessage.value = fallback; }
async function fetchPermissions(page = 1): Promise<void> { loading.value = true; selectedIds.value = []; errorMessage.value = ''; try { const response = await http.get('/permissions', { params: { page, per_page: 15, search: search.value || undefined, group: group.value || undefined, guard: guard.value || undefined } }); permissions.value = response.data.data; pagination.value = response.data.meta; } catch (error) { handleError(error, 'Unable to load permissions.'); } finally { loading.value = false; } }
async function fetchGroups(): Promise<void> { try { const response = await http.get('/permissions', { params: { per_page: 100 } }); groupOptions.value = Array.from(new Set((response.data.data as PermissionRecord[]).map((item) => item.group_key))).sort(); } catch (error) { handleError(error, 'Unable to load permission groups.'); } }
function openCreate(): void { editingPermission.value = null; form.name = ''; validationErrors.value = {}; errorMessage.value = ''; modalOpen.value = true; }
function openEdit(permission: PermissionRecord): void { if (!permission.can_rename) return; editingPermission.value = permission; form.name = permission.name; validationErrors.value = {}; errorMessage.value = ''; modalOpen.value = true; }
function openDetails(permission: PermissionRecord): void { selectedPermission.value = permission; detailsOpen.value = true; }
function toggleAll(event: Event): void { selectedIds.value = (event.target as HTMLInputElement).checked ? permissions.value.filter((item) => item.can_trash).map((item) => item.id) : []; }
function toggleSelected(id: number, event: Event): void { selectedIds.value = (event.target as HTMLInputElement).checked ? [...selectedIds.value, id] : selectedIds.value.filter((value) => value !== id); }
async function submit(): Promise<void> { submitting.value = true; validationErrors.value = {}; errorMessage.value = ''; try { if (editingPermission.value) { await http.put(`/permissions/${editingPermission.value.id}`, form); message.value = 'Permission updated successfully.'; } else { await http.post('/permissions', form); message.value = 'Permission created successfully.'; } modalOpen.value = false; await Promise.all([fetchPermissions(pagination.value.current_page), fetchGroups()]); } catch (error) { handleError(error, 'Unable to save this permission.'); } finally { submitting.value = false; } }
async function moveToTrash(permission: PermissionRecord): Promise<void> { if (!permission.can_trash || !window.confirm(`Move ${permission.name} to Trash?`)) return; try { await http.delete(`/permissions/${permission.id}`); message.value = 'Permission moved to Trash.'; await Promise.all([fetchPermissions(pagination.value.current_page), fetchGroups()]); } catch (error) { handleError(error, 'Unable to move this permission to Trash.'); } }
async function applyBulkAction(): Promise<void> { if (bulkAction.value !== 'trash' || !selectedIds.value.length || !window.confirm(`Move ${selectedCount.value} selected permission(s) to Trash?`)) return; bulkSubmitting.value = true; try { await http.post('/permissions/bulk-action', { action: 'trash', ids: selectedIds.value }); message.value = 'Selected permissions moved to Trash.'; bulkAction.value = ''; await Promise.all([fetchPermissions(pagination.value.current_page), fetchGroups()]); } catch (error) { handleError(error, 'Unable to apply the bulk action.'); } finally { bulkSubmitting.value = false; } }
function formatDate(value: string | null): string { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
onMounted(() => Promise.all([fetchPermissions(), fetchGroups()]));
</script>

<template>
    <div class="module-page">
        <div class="module-page-heading"><div class="module-title-wrap"><span class="module-title-icon"><i class="bi bi-key-fill"></i></span><div><h3 class="mb-1">Permissions Management</h3><p class="text-body-secondary mb-0">Manage granular access permissions for CoachDesk modules.</p></div></div><nav class="module-breadcrumb"><RouterLink :to="{ name: 'dashboard' }"><i class="bi bi-house-fill"></i></RouterLink><i class="bi bi-chevron-right"></i><span>Access Control</span><i class="bi bi-chevron-right"></i><strong>Permissions List</strong></nav></div>
        <div class="module-toolbar"><button v-if="canCreate" class="btn btn-primary" type="button" @click="openCreate"><i class="bi bi-plus-circle me-1"></i>Add New Permission</button><RouterLink v-if="canRestore || canForceDelete" :to="{ name: 'permissions-trash' }" class="btn btn-outline-danger"><i class="bi bi-trash3 me-1"></i>Trash Bin</RouterLink><div class="bulk-toolbar"><select v-model="bulkAction" class="form-select"><option value="">-- Bulk Actions --</option><option v-if="canDelete" value="trash">Move to Trash</option></select><button class="btn btn-secondary" :disabled="!selectedCount || !bulkAction || bulkSubmitting" @click="applyBulkAction">{{ bulkSubmitting ? 'Applying...' : 'APPLY' }}</button><span v-if="selectedCount" class="selected-count">{{ selectedCount }} selected</span></div></div>
        <div v-if="message" class="alert alert-success">{{ message }}</div><div v-if="errorMessage" class="alert alert-danger">{{ errorMessage }}</div>
        <div class="card module-filter-card"><div class="card-body"><form class="row g-3 align-items-end" @submit.prevent="fetchPermissions(1)"><div class="col-6 col-md-2"><label class="form-label">GUARD NAME</label><select v-model="guard" class="form-select"><option value="">All Guards</option><option value="web">web</option></select></div><div class="col-6 col-md-3"><label class="form-label">GROUP NAME</label><select v-model="group" class="form-select"><option value="">All Groups</option><option v-for="item in groupOptions" :key="item" :value="item">{{ item.replaceAll('_', ' ') }}</option></select></div><div class="col-12 col-md-5"><label class="form-label">SEARCH</label><input v-model.trim="search" class="form-control" type="search" placeholder="Search by permission name..."></div><div class="col-12 col-md-2 d-flex gap-2"><button class="btn btn-primary flex-fill" type="submit"><i class="bi bi-search"></i></button><button class="btn btn-outline-danger flex-fill" type="button" @click="search = ''; group = ''; guard = ''; fetchPermissions(1)"><i class="bi bi-arrow-counterclockwise"></i>Reset</button></div></form></div></div>
        <div class="card module-list-card"><div class="card-header"><h5 class="card-title"><i class="bi bi-list-ul text-primary me-2"></i>Permission List</h5></div><div class="table-responsive"><table class="table table-hover align-middle module-table mb-0"><thead><tr><th class="text-center"><input class="form-check-input" type="checkbox" :checked="allSelected" :disabled="loading" @change="toggleAll"></th><th>ID</th><th>Permission Name</th><th>Guard Name</th><th>Group Name</th><th>Created At</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="text-center py-5"><span class="spinner-border spinner-border-sm me-2"></span>Loading permissions...</td></tr><tr v-else-if="!permissions.length"><td colspan="7" class="module-empty">No permissions found.</td></tr><template v-else><tr v-for="permission in permissions" :key="permission.id"><td class="text-center"><input class="form-check-input" type="checkbox" :checked="selectedIds.includes(permission.id)" :disabled="!permission.can_trash" @change="toggleSelected(permission.id, $event)"></td><td><span class="text-primary fw-semibold">#{{ permission.id }}</span></td><td><code>{{ permission.name }}</code><span v-if="permission.is_protected" class="badge text-bg-danger ms-2">Protected</span></td><td><span class="badge text-bg-secondary">{{ permission.guard_name }}</span></td><td><span class="badge text-bg-light border">{{ permission.group }}</span></td><td>{{ formatDate(permission.created_at) }}</td><td class="text-end"><div class="btn-group btn-group-sm"><button class="btn btn-outline-info" title="View" @click="openDetails(permission)"><i class="bi bi-eye"></i></button><button v-if="canUpdate" class="btn btn-outline-primary" title="Edit" :disabled="!permission.can_rename" @click="openEdit(permission)"><i class="bi bi-pencil"></i></button><button v-if="canDelete" class="btn btn-outline-danger" title="Move to Trash" :disabled="!permission.can_trash" @click="moveToTrash(permission)"><i class="bi bi-trash3"></i></button></div></td></tr></template></tbody></table></div><div class="card-footer d-flex flex-wrap justify-content-between align-items-center gap-2"><span class="small text-body-secondary">{{ pagination.total }} permissions</span><div class="btn-group btn-group-sm"><button class="btn btn-outline-secondary" :disabled="pagination.current_page <= 1 || loading" @click="fetchPermissions(pagination.current_page - 1)">Previous</button><button class="btn btn-outline-secondary" disabled>Page {{ pagination.current_page }} of {{ pagination.last_page }}</button><button class="btn btn-outline-secondary" :disabled="pagination.current_page >= pagination.last_page || loading" @click="fetchPermissions(pagination.current_page + 1)">Next</button></div></div></div>
    </div>

    <BaseModal v-model="modalOpen" :title="editingPermission ? 'Edit Permission' : 'Create Permission'"><form @submit.prevent="submit"><div class="modal-body"><div v-if="errorMessage" class="alert alert-danger py-2">{{ errorMessage }}</div><label class="form-label fw-semibold">Permission name</label><input v-model.trim="form.name" class="form-control" :class="{ 'is-invalid': fieldError('name') }" placeholder="e.g. students.view" required><div class="invalid-feedback">{{ fieldError('name') }}</div><div class="form-text">Use the format <code>module.action</code>. Guard is fixed to <code>web</code>.</div></div><div class="modal-footer"><button type="button" class="btn btn-light border" @click="modalOpen = false">Cancel</button><button type="submit" class="btn btn-primary" :disabled="submitting"><span v-if="submitting" class="spinner-border spinner-border-sm me-1"></span>{{ submitting ? 'Saving...' : editingPermission ? 'Save Changes' : 'Create Permission' }}</button></div></form></BaseModal>
    <BaseModal v-model="detailsOpen" title="Permission Details"><div v-if="selectedPermission" class="modal-body"><dl class="row mb-0"><dt class="col-sm-4">Permission</dt><dd class="col-sm-8"><code>{{ selectedPermission.name }}</code></dd><dt class="col-sm-4">Guard</dt><dd class="col-sm-8">{{ selectedPermission.guard_name }}</dd><dt class="col-sm-4">Group</dt><dd class="col-sm-8">{{ selectedPermission.group }}</dd><dt class="col-sm-4">Assigned Roles</dt><dd class="col-sm-8">{{ selectedPermission.roles_count }}</dd><dt class="col-sm-4">Direct Users</dt><dd class="col-sm-8">{{ selectedPermission.users_count }}</dd></dl></div><div class="modal-footer"><button class="btn btn-light border" @click="detailsOpen = false">Close</button></div></BaseModal>
</template>
